  S.utilityClimbs = retired.filter((l, i) => retired.findIndex(o => o.kind === l.kind && o.tx === l.tx && o.ty === l.ty && o.bz === l.bz) === i);
  S.ladders = S.ladders.filter(physicalAccess); S.lvl = null;
