  ctx.fillStyle='#a9a492';ctx.beginPath();ctx.ellipse(0,0,15,8,0,0,TAU);ctx.fill();ctx.fillStyle='#4e584c';ctx.beginPath();ctx.ellipse(0,-1,12,5,0,0,TAU);ctx.fill();
