function wirePt(w, s) { const cx = (w.a.dx + w.b.dx) / 2, cy = (w.a.dy + w.b.dy) / 2 + w.sag * 2, u = 1 - s; return { x: u * u * w.a.dx + 2 * u * s * cx + s * s * w.b.dx, y: u * u * w.a.dy + 2 * u * s * cy + s * s * w.b.dy }; }
