function wireEnd() { const P = S.player, W_ = P.wire; if (!W_) return null; const tol = 44 / W_.w.L; return W_.s <= tol ? W_.w.a : W_.s >= 1 - tol ? W_.w.b : null; }
// 줄에서 벗어나는 환경 행동은 아래 적을 공격할 수 있는지와 따로 계산한다.
