  if (n.roof) { startTrav({ pts: [{ x: hx, y: hy, f: 0 }, { x: n.x, y: n.y, f: 1 }], dur: 0.45, phases: [{ to: 1, pose: 'vault' }], end: () => { P.z = n.z; P.x = n.x; P.y = n.y; setLayer(0); } }); return; }
