  S.corpses.push(c);
  if (g.target) { const left = S.guards.filter(o => o.target && !targetEliminated(o)).length; toast(left ? `표적 제거(사고) — 남은 표적 ${left}` : '표적 제거 — 사고로 보인다', 3, 'good'); }
  if (S.fuseGuard === g) S.fuseGuard = null;
