  for(let y=Math.floor(vy/192)*192;y<Math.min(height,vy+vh);y+=192)if(y+192>0){for(const x of [0,width+32]){ctx.save();ctx.translate(x,y);ctx.rotate(Math.PI/2);ctx.drawImage(wall,0,0);ctx.restore();}}
