  const g = y.createLinearGradient(0, 0, 0, H); g.addColorStop(0, 'rgba(10,13,22,.5)'); g.addColorStop(1, 'rgba(10,13,22,0)'); y.fillStyle = g; y.fillRect(0, 0, W, H);
  fc.drawImage(b, 0, 0); fc.drawImage(t, 0, 0);
