  const P = S.player;
  if (paused || tactical || S.keypad || DLG.modal || S.over || actionBusy() || flOf(P)!==envPicker.fl || (P.z||0)!==envPicker.z || dist(P.x,P.y,envPicker.x,envPicker.y)>8) { closeEnvPicker(); return; }
  const live = new Set(envChoices().map(envToken));
