  const a=envAction(); if(a.k==='none' || !(a.choices>1 || S.envExplicit)) return;
  if(a.c&&a.k!=='retrieve'){if(attackAction().c===a.c)return;ctx.save();ctx.setLineDash([4,3]);drawTargetRing(a.c,'#e6d9ae',a.c);ctx.restore();return;}
