    path: RUN.path.join(';'),
    ev: (S && S.events || []).slice(-300).map(e => [e.k, Math.round(e.x / 8), Math.round(e.y / 8), Math.round(e.t - RUN.g0)].join(',')).join(';'),
    last: S ? [Math.round(S.player.x / 8), Math.round(S.player.y / 8), flOf(S.player)].join(',') : ''
